"use client";

import React, { useState } from "react";
import { usePathname, useRouter } from "next/navigation";
import Link from "next/link";
import { Menu, X, ArrowLeft, Info, Mail, HelpCircle, RefreshCcw, Truck, XCircle, Shield, FileText } from "lucide-react";

// Updated to match your exact folder names
export const helpSections = [
  { id: "about", label: "About Us", href: "/help/about", icon: <Info size={20} />, tagline: "The story behind the brand." },
  { id: "contact", label: "Contact Us", href: "/help/contact", icon: <Mail size={20} />, tagline: "We're here to help you." },
  { id: "faq", label: "FAQ", href: "/help/faq", icon: <HelpCircle size={20} />, tagline: "Quick answers to common queries." },
  { id: "returns", label: "Returns", href: "/help/returns", icon: <RefreshCcw size={20} />, tagline: "Manage your returns." },
  { id: "shipping", label: "Shipping", href: "/help/shipping", icon: <Truck size={20} />, tagline: "Global delivery details." },
  { id: "refund-policy", label: "Refund Policy", href: "/help/refund-policy", icon: <RefreshCcw size={20} />, tagline: "Simple, no-fuss refunds." },
  { id: "privacy-policy", label: "Privacy Policy", href: "/help/privacy-policy", icon: <Shield size={20} />, tagline: "How we protect your data." },
  { id: "terms", label: "Terms", href: "/help/terms", icon: <FileText size={20} />, tagline: "The fine print." },
  { id: "size-guide", label: "Size Guide", href: "/help/size-guide", icon: <FileText size={20} />, tagline: "Find your perfect fit." },
];

export default function HelpLayout({ children }: { children: React.ReactNode }) {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const pathname = usePathname();
  const router = useRouter();

  const activeSection = helpSections.find((s) => s.href === pathname);

  return (
    <div className="min-h-screen bg-background text-foreground font-sans">
      {/* --- STICKY NAV BAR --- */}
      <header className="fixed top-0 z-50 w-full border-b border-border bg-background/80 backdrop-blur-md">
        <div className="max-w-7xl mx-auto h-20 px-6 flex items-center justify-between">
          <button onClick={() => router.back()} className="flex items-center gap-2 group">
            <ArrowLeft size={20} />
            <span className="text-sm font-bold uppercase tracking-widest hidden md:block">Back</span>
          </button>

          <div className="flex flex-col items-center">
            <span className="text-[10px] uppercase tracking-[0.3em] text-foreground-subtle font-bold">Help Center</span>
            <span className="text-sm font-black uppercase tracking-tighter">
              {activeSection?.label || "Directory"}
            </span>
          </div>

          <button onClick={() => setIsMenuOpen(true)} className="flex items-center gap-3">
            <span className="text-xs font-bold uppercase tracking-widest hidden md:block">Sections</span>
            <div className="p-2 text-foreground rounded-full">
              <Menu size={20} />
            </div>
          </button>
        </div>
      </header>

      {/* --- NAVIGATION OVERLAY --- */}
      <div className={`fixed inset-0 z-[60] bg-background transition-transform duration-500 ease-in-out ${isMenuOpen ? "translate-x-0" : "translate-x-full"}`}>
        <div className="h-20 px-6 flex items-center justify-end max-w-7xl mx-auto">
          <button onClick={() => setIsMenuOpen(false)} className="p-3 hover:bg-background-muted rounded-full">
            <X size={32} />
          </button>
        </div>
        <div className="max-w-3xl mx-auto px-6 py-12">
          <nav className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {helpSections.map((item) => (
              <Link
                key={item.id}
                href={item.href}
                onClick={() => setIsMenuOpen(false)}
                className={`flex items-start gap-4 p-6 rounded-[2rem] border transition-all ${
                  pathname === item.href ? "bg-brand text-brand-foreground border-brand" : "bg-background-muted border-transparent hover:border-border"
                }`}
              >
                <div className={`p-3 rounded-2xl ${pathname === item.href ? "bg-white/20" : "bg-background border border-border"}`}>
                  {item.icon}
                </div>
                <div>
                  <p className="font-bold text-lg leading-none mb-1">{item.label}</p>
                  <p className={`text-xs ${pathname === item.href ? "opacity-80" : "text-foreground-subtle"}`}>{item.tagline}</p>
                </div>
              </Link>
            ))}
          </nav>
        </div>
      </div>

      {/* --- CONTENT AREA --- */}
      <main className="pt-20">
        {children}
      </main>
    </div>
  );
}